const lockAuditPeriodsOverlapping = `-- name: LockAuditPeriodsOverlapping :many
SELECT id, tenant_id, name, framework_version_id, period_start, period_end, status, frozen_at, frozen_hash, frozen_by, created_by, created_at, updated_at
FROM audit_periods
WHERE tenant_id    = $1
  AND period_start <= $2::date
  AND period_end   >= $3::date
ORDER BY id
FOR UPDATE
`

type LockAuditPeriodsOverlappingParams struct {
	TenantID pgtype.UUID `json:"tenant_id"`
	LastDay  pgtype.Date `json:"last_day"`
	FirstDay pgtype.Date `json:"first_day"`
}

// #1742: the periods whose window holds a date in [first_day, last_day],
// locked FOR UPDATE so a historical import and a freeze of the same period
// serialise: the import decides "open or frozen" on a row no freeze can
// change until the import commits.
func (q *Queries) LockAuditPeriodsOverlapping(ctx context.Context, arg LockAuditPeriodsOverlappingParams) ([]AuditPeriod, error) {
	rows, err := q.db.Query(ctx, lockAuditPeriodsOverlapping, arg.TenantID, arg.LastDay, arg.FirstDay)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []AuditPeriod
	for rows.Next() {
		var i AuditPeriod
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.Name,
			&i.FrameworkVersionID,
			&i.PeriodStart,
			&i.PeriodEnd,
			&i.Status,
			&i.FrozenAt,
			&i.FrozenHash,
			&i.FrozenBy,
			&i.CreatedBy,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockTenantEvidenceFreeze = `-- name: LockTenantEvidenceFreeze :exec
SELECT pg_advisory_xact_lock(14, hashtext($1::uuid::text))
`

// #1742: serialises Freeze against a historical evidence import in one
// tenant for the rest of the transaction. Freeze takes it before hashing;
// the import takes it as its first statement. Namespace 14 is
// advisorylock.TenantEvidenceFreeze.
func (q *Queries) LockTenantEvidenceFreeze(ctx context.Context, tenantID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, lockTenantEvidenceFreeze, tenantID)
	return err
}

const lockTenantEvidenceFreezeShared = `-- name: LockTenantEvidenceFreezeShared :exec
SELECT pg_advisory_xact_lock_shared(14, hashtext($1::uuid::text))
`

// #3038: the shared mode of LockTenantEvidenceFreeze, which every live
// ingest takes just before it inserts a ledger row and holds to commit.
// Ingests do not block each other; a freeze waits until every ingest that
// holds it has committed, so it hashes with their rows in view. Run
// CountPeriodsFrozenSinceTxStart after it, as its own statement.
func (q *Queries) LockTenantEvidenceFreezeShared(ctx context.Context, tenantID pgtype.UUID) error {
	_, err := q.db.Exec(ctx, lockTenantEvidenceFreezeShared, tenantID)
	return err
}

const minFrozenAtOverlappingWindow = `-- name: MinFrozenAtOverlappingWindow :one
SELECT min(frozen_at)::timestamptz AS min_frozen_at
FROM audit_periods
WHERE tenant_id = $1
  AND status    = 'frozen'
  AND frozen_at IS NOT NULL
  AND (period_start::timestamptz, (period_end + 1)::timestamptz)
      OVERLAPS ($2::timestamptz, $3::timestamptz)
`

type MinFrozenAtOverlappingWindowParams struct {
	TenantID   pgtype.UUID        `json:"tenant_id"`
	WindowFrom pgtype.Timestamptz `json:"window_from"`
	WindowTo   pgtype.Timestamptz `json:"window_to"`
}

// Slice 135 AC-12: the earliest `frozen_at` across all FROZEN
// audit_periods whose [period_start, period_end] intersects the
// supplied [from_ts, to_ts] export window. Used by the audit-log
// export endpoint to clamp the effective `to` boundary so an export
// inside (or overlapping) a frozen period only surfaces rows whose
// observed_at (= occurred_at on the audit-log union) is <= the
// earliest applicable frozen_at.
//
// Returns NULL when no frozen period overlaps the window (live
// horizon — no clamp applied).
//
// RLS-aware: runs under `tenancy.ApplyTenant` as atlas_app; the
// tenant_id filter is defense-in-depth on top of the RLS policy.
// Period-end is a DATE; cast to inclusive end-of-day timestamptz so
// a request whose `from` is the last hour of a frozen period's last
// day still counts as overlapping.
func (q *Queries) MinFrozenAtOverlappingWindow(ctx context.Context, arg MinFrozenAtOverlappingWindowParams) (pgtype.Timestamptz, error) {
	row := q.db.QueryRow(ctx, minFrozenAtOverlappingWindow, arg.TenantID, arg.WindowFrom, arg.WindowTo)
	var min_frozen_at pgtype.Timestamptz
	err := row.Scan(&min_frozen_at)
	return min_frozen_at, err
}

const setPopulationFrozenAt = `-- name: SetPopulationFrozenAt :exec
UPDATE populations
SET frozen_at = $3
WHERE tenant_id       = $1
  AND audit_period_id = $2
  AND frozen_at IS NULL
`

type SetPopulationFrozenAtParams struct {
	TenantID      pgtype.UUID        `json:"tenant_id"`
	AuditPeriodID pgtype.UUID        `json:"audit_period_id"`
	FrozenAt      pgtype.Timestamptz `json:"frozen_at"`
}

// Stamp populations.frozen_at from the parent period's frozen_at. Called
// both at attach-time (if the period is already frozen) and at freeze-time
// (for all populations already attached to this period). The slice-026
// query path then enforces `observed_at <= populations.frozen_at` on
// subsequent draws.
func (q *Queries) SetPopulationFrozenAt(ctx context.Context, arg SetPopulationFrozenAtParams) error {
	_, err := q.db.Exec(ctx, setPopulationFrozenAt, arg.TenantID, arg.AuditPeriodID, arg.FrozenAt)
	return err
}

const writeAuditPeriodLog = `-- name: WriteAuditPeriodLog :one
INSERT INTO audit_period_audit_log (
    id, tenant_id, audit_period_id, action, actor, detail, occurred_at, subject_module
)
VALUES ($1, $2, $3, $4, $5, $6, now(), 'core')
RETURNING id, tenant_id, audit_period_id, action, actor, detail, occurred_at, subject_module
`

type WriteAuditPeriodLogParams struct {
	ID            pgtype.UUID `json:"id"`
	TenantID      pgtype.UUID `json:"tenant_id"`
	AuditPeriodID pgtype.UUID `json:"audit_period_id"`
	Action        string      `json:"action"`
	Actor         string      `json:"actor"`
	Detail        []byte      `json:"detail"`
}

// Append-only lifecycle log. action is constrained at the DB layer
// (period_created | period_frozen | freeze_rejected_already_frozen |
// population_attached). detail is a free-form JSONB for action-specific
// payload (e.g., the rejected freeze attempt records the offending actor).
//
// Slice 180: explicit `subject_module='core'` (column defaults to 'core' at
// the DB layer; explicit-is-clearer per AC-5).
func (q *Queries) WriteAuditPeriodLog(ctx context.Context, arg WriteAuditPeriodLogParams) (AuditPeriodAuditLog, error) {
	row := q.db.QueryRow(ctx, writeAuditPeriodLog,
		arg.ID,
		arg.TenantID,
		arg.AuditPeriodID,
		arg.Action,
		arg.Actor,
		arg.Detail,
	)
	var i AuditPeriodAuditLog
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.AuditPeriodID,
		&i.Action,
		&i.Actor,
		&i.Detail,
		&i.OccurredAt,
		&i.SubjectModule,
	)
	return i, err
}
